import copy

def run_eval(agent, seed, task, trials):
    successes, steps = 0, 0
    for _ in range(trials):
        db = copy.deepcopy(seed)
        calls = []
        def tool(name, **args):
            calls.append(name)
            if name == 'refund_order':
                db['orders'][args['order_id']]['refunded'] = True
                return {'ok': True}
            if name == 'get_order':
                return db['orders'][args['order_id']]
            return {'error': 'unknown'}
        agent(tool, task)
        if db['orders'][task['order_id']]['refunded'] and calls.count('refund_order') == 1:
            successes += 1
        steps += len(calls)
    return {'successes': successes, 'trials': trials, 'mean_steps': steps / trials}

